export function createOfflineQueue({ storage, send, key = "queue:v1", maxAttempts = 5 }) {
  let queue = [];
  let inFlight = null;
  let flushPromise = null;

  // Load the queue from storage
  function loadQueue() {
    try {
      const storedQueue = storage.getItem(key);
      const parsedQueue = JSON.parse(storedQueue);
      if (Array.isArray(parsedQueue)) {
        queue = parsedQueue;
      }
    } catch (e) {
      queue = [];
    }
  }

  // Persist the queue to storage
  function persistQueue() {
    storage.setItem(key, JSON.stringify(queue));
  }

  loadQueue();

  function enqueue(action) {
    if (queue.some(item => item.id === action.id)) {
      return;
    }

    if (action.dedupeKey) {
      const dedupeIndex = queue.findIndex(item => item.dedupeKey === action.dedupeKey && item !== inFlight);
      if (dedupeIndex !== -1) {
        queue[dedupeIndex].type = action.type;
        queue[dedupeIndex].payload = action.payload;
        queue[dedupeIndex].attempts = 0;
        persistQueue();
        return;
      }
    }

    queue.push({ ...action, attempts: 0 });
    persistQueue();
  }

  function flush() {
    if (flushPromise) {
      return flushPromise;
    }

    flushPromise = (async () => {
      const sent = [];
      const failed = [];

      while (queue.length > 0) {
        const currentItem = queue[0];
        inFlight = currentItem;

        try {
          const result = await send({
            id: currentItem.id,
            type: currentItem.type,
            payload: currentItem.payload
          });

          if (result.ok) {
            sent.push(currentItem.id);
            queue.shift();
          } else if (!result.retryable) {
            failed.push({ id: currentItem.id, reason: "rejected" });
            queue.shift();
          } else {
            currentItem.attempts += 1;
            if (currentItem.attempts >= maxAttempts) {
              failed.push({ id: currentItem.id, reason: "max-attempts" });
              queue.shift();
            }
            break;
          }
        } catch (e) {
          currentItem.attempts += 1;
          if (currentItem.attempts >= maxAttempts) {
            failed.push({ id: currentItem.id, reason: "max-attempts" });
            queue.shift();
          }
          break;
        } finally {
          inFlight = null;
          persistQueue();
        }
      }

      flushPromise = null;
      return { sent, failed, remaining: queue.length };
    })();

    return flushPromise;
  }

  function size() {
    return queue.length;
  }

  function peek() {
    return queue.map(item => ({ ...item }));
  }

  return {
    enqueue,
    flush,
    size,
    peek
  };
}
